import requests
import time
import pandas as pd
import logging
from langdetect import detect, LangDetectException
from tqdm import tqdm

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')

def fetch_lyrics_ovh(artist: str, song: str, timeout=10, retries=2) -> str:
    """
    Obtiene la letra usando la API pública de lyrics.ovh.
    """
    url = f'https://api.lyrics.ovh/v1/{artist}/{song}'
    for attempt in range(retries):
        try:
            resp = requests.get(url, timeout=timeout)
            if resp.status_code == 200:
                data = resp.json()
                return data.get('lyrics')
            elif resp.status_code == 404:
                # No encontrada
                return None
            else:
                logging.warning(f'Error {resp.status_code} para {artist} - {song}')
        except requests.RequestException as e:
            logging.error(f'Error en request para {artist} - {song}: {e}')
        time.sleep(0.5)  # pausa corta entre reintentos
    return None

def detectar_idioma(texto: str) -> str:
    if not isinstance(texto, str) or len(texto.strip()) < 50:
        return 'unknown'
    try:
        return detect(texto[:1000])
    except LangDetectException:
        return 'unknown'


