def scrape_lyrics_ovh(songs_by_genre, max_per_genre, max_total, existing_df=None):
    """
    Scrapea letras usando la API de lyrics.ovh para un catálogo de canciones.
    Retorna un DataFrame con las canciones obtenidas.
    """
    records = []
    total_scraped = 0

    # Evitar duplicados con datos existentes
    existing = set()
    if existing_df is not None and 'Artist' in existing_df.columns and 'Song' in existing_df.columns:
        existing = set(zip(existing_df['Artist'], existing_df['Song']))

    for genre, songs in songs_by_genre.items():
        if total_scraped >= max_total:
            break
        limit = min(max_per_genre, max_total - total_scraped)
        genre_records = 0
        for artist, song in tqdm(songs, desc=f'Scraping {genre}', unit='canciones'):
            if genre_records >= limit:
                break
            if (artist, song) in existing:
                continue
            lyrics = fetch_lyrics_ovh(artist, song)
            if lyrics:
                lang = detectar_idioma(lyrics)
                if lang in ['en', 'unknown']:
                    records.append({
                        'Song': song,
                        'Song year': None,
                        'Artist': artist,
                        'Genre': genre,
                        'Lyrics': lyrics,
                        'Source': 'lyrics_ovh_api',
                        'URL': f'https://api.lyrics.ovh/v1/{artist}/{song}',
                        'Language': lang,
                    })
                    genre_records += 1
                    total_scraped += 1
                    time.sleep(0.2)  # pausa ligera
        print(f'  {genre}: {genre_records} canciones obtenidas.')

    df = pd.DataFrame(records)
    return df
